Given the root of a binary tree, find its diameter. The diameter of a tree is defined as the number of edges in the longest path between any two nodes.Examples:Input: The binary tree for this example is shown in the image below.Output: 2Explanation: The longest path has 2 edges ( the path  2 -> 1 -> 3 ).Input: The binary tree for this example is shown in the image below.Output: 4Explanation: The longest path has 4 edges ( the path 5 -> 3 -> 2 -> 4 -> 6 ).Try It YourselfTable of Content[Naive Approach] By Calculating Height For Each Node - O(n^2) Time and O(h) Space[Expected Approach] Using Single Traversal - O(n) Time and O(h) Space[Naive Approach] By Calculating Height For Each Node - O(n2) Time and O(h) SpaceThe core idea involves recursively traversing the tree. At each node, we determine the heights of its left and right subtrees and update the maximum diameter by calculating the sum of these heights.
            C++

    #include <iostream>
#include <algorithm>
using namespace std;

// Node Structure
class Node {
public:
    int data;
    Node *left, *right;
    Node(int x) {
        data = x;
        left = nullptr;
        right = nullptr;
    }
};

// Function to compute the height of a tree.
int height(Node* root) {

    if (root == nullptr)
        return 0;

    // If tree is not empty then height = 1 + max of left height and right heights
    return 1 + max(height(root->left), 
                   height(root->right));
}

// Function to get diameter of a binary tree
int diameter(Node* root) {

    if (root == nullptr)
        return 0;

    // Get the height of left and right sub-trees
    int lheight = height(root->left);
    int rheight = height(root->right);

    // Get the diameter of left and right sub-trees
    int ldiameter = diameter(root->left);
    int rdiameter = diameter(root->right);

    return max({lheight + rheight, ldiameter, rdiameter});
}

int main() {

    Node* root = new Node(1);
    root->right = new Node(2);
    root->right->left = new Node(3);
    root->right->right = new Node(4);
  	root->right->left->left = new Node(5);
  	root->right->right->right = new Node(6);
    cout << diameter(root) << endl;

    return 0;
}


